#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelForeachLerpScalar {
public:
    __aicore__ inline KernelForeachLerpScalar() {}

    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2, GM_ADDR y,
        int64_t formerNum, int64_t formerLength,
        int64_t tailLength, int64_t tileLength,
        float scalarWeight)
    {
        this->scalarWeight = scalarWeight;

        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, formerLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, tailLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX1, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX2, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) < sizeof(float)) {
            pipe.InitBuffer(tmpBufX1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBufX2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBufDiff, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        if (alignNum == 0) { alignNum = 1; }
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> x1Local = inQueueX1.AllocTensor<T>();
        AscendC::DataCopy(x1Local, x1Gm[progress * this->tileLength], curTileLength);
        inQueueX1.EnQue(x1Local);

        AscendC::LocalTensor<T> x2Local = inQueueX2.AllocTensor<T>();
        AscendC::DataCopy(x2Local, x2Gm[progress * this->tileLength], curTileLength);
        inQueueX2.EnQue(x2Local);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> x1Local = inQueueX1.DeQue<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: compute directly on FP32
            // diff = x2 - x1
            AscendC::Sub(yLocal, x2Local, x1Local, curTileLength);
            // yLocal = weight * diff
            AscendC::Muls(yLocal, yLocal, this->scalarWeight, curTileLength);
            // yLocal = x1 + yLocal
            AscendC::Add(yLocal, x1Local, yLocal, curTileLength);
        } else {
            // FP16 / BF16 path: cast to FP32, compute, cast back
            AscendC::LocalTensor<float> x1Fp32 = tmpBufX1.Get<float>();
            AscendC::LocalTensor<float> x2Fp32 = tmpBufX2.Get<float>();
            AscendC::LocalTensor<float> diffFp32 = tmpBufDiff.Get<float>();

            // Cast inputs to FP32
            AscendC::Cast(x1Fp32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x2Fp32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);

            // diff = x2 - x1
            AscendC::Sub(diffFp32, x2Fp32, x1Fp32, curTileLength);
            // diff = weight * diff
            AscendC::Muls(diffFp32, diffFp32, this->scalarWeight, curTileLength);
            // diff = x1 + diff  (final result in FP32)
            AscendC::Add(diffFp32, x1Fp32, diffFp32, curTileLength);

            // Cast back to original dtype
            AscendC::Cast(yLocal, diffFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX2.FreeTensor(x2Local);
        inQueueX1.FreeTensor(x1Local);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX1;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX2;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufDiff;
    AscendC::GlobalTensor<T> x1Gm;
    AscendC::GlobalTensor<T> x2Gm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    float scalarWeight;
};

extern "C" __global__ __aicore__ void foreach_lerp_scalar(
    GM_ADDR x1, GM_ADDR x2, GM_ADDR y,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize, float scalarWeight)
{
    if (dtypeSize == static_cast<int64_t>(sizeof(float))) {
        KernelForeachLerpScalar<float> op;
        op.Init(x1, x2, y, formerNum, formerLength, tailLength, tileLength, scalarWeight);
        op.Process();
    } else {
        KernelForeachLerpScalar<half> op;
        op.Init(x1, x2, y, formerNum, formerLength, tailLength, tileLength, scalarWeight);
        op.Process();
    }
}
