#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_lerp_scalar.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor foreach_lerp_scalar(
    const at::Tensor &x1_flat,
    const at::Tensor &x2_flat,
    double scalar_weight)
{
    // ---- 输入校验 ----
    TORCH_CHECK(x1_flat.scalar_type() == at::kHalf ||
                x1_flat.scalar_type() == at::kFloat ||
                x1_flat.scalar_type() == at::kBFloat16,
                "foreach_lerp_scalar: only float16, float32 and bfloat16 are supported, got ",
                x1_flat.scalar_type());
    TORCH_CHECK(x1_flat.scalar_type() == x2_flat.scalar_type(),
                "foreach_lerp_scalar: x1 and x2 must have the same dtype");
    TORCH_CHECK(x1_flat.numel() == x2_flat.numel(),
                "foreach_lerp_scalar: x1 and x2 must have the same number of elements");
    TORCH_CHECK(x1_flat.is_contiguous() && x2_flat.is_contiguous(),
                "foreach_lerp_scalar: inputs must be contiguous");

    at::Tensor output = at::empty_like(x1_flat);

    int64_t totalLength = x1_flat.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = static_cast<int64_t>(x1_flat.element_size());

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCoreAlign = totalLength;
    if (totalLength >= coreNum) {
        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
        int64_t alignNum = CACHE_LINE_BYTE_LENGTH / dtypeSize;
        if (alignNum == 0) { alignNum = 1; }
        totalLengthCoreAlign = ((totalLengthCore + alignNum - 1) / alignNum) * alignNum;
    }

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // bufferCoefficient: 32 for FP32, 24 for FP16/BF16
    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) { tileLength = alignElements; }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    float weight = static_cast<float>(scalar_weight);

    EXEC_KERNEL_CMD(foreach_lerp_scalar, blockDim,
                    x1_flat, x2_flat, output,
                    formerNum, formerLength, tailLength, tileLength,
                    dtypeSize, weight);

    return output;
}

}  // namespace ascend_kernel
