project(foreach_lerp_scalar LANGUAGES CXX)

# ---- AscendC kernel compile settings ----
include(${ASCEND_CANN_PACKAGE_PATH}/cmake/ascendc.cmake)

set(OP_NAME foreach_lerp_scalar)

# ---- Collect source files ----
set(OP_SRCS
    ${CMAKE_CURRENT_SOURCE_DIR}/op_host/${OP_NAME}.cpp
)

set(OP_KERNEL_SRCS
    ${CMAKE_CURRENT_SOURCE_DIR}/op_kernel/${OP_NAME}.cpp
)

# ---- Build shared library ----
ascendc_library(${OP_NAME}_ext SHARED
    ${OP_SRCS}
    ${OP_KERNEL_SRCS}
)

target_include_directories(${OP_NAME}_ext PRIVATE
    ${CMAKE_CURRENT_SOURCE_DIR}/utils
