10	namespace ascend_kernel {
11	
12	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
13	
14	at::Tensor foreach_lerp_scalar(
15	    const at::Tensor &x1_flat,
16	    const at::Tensor &x2_flat,
17	    double scalar_weight)
18	{
19	    // ---- 输入校验 ----
20	    TORCH_CHECK(x1_flat.scalar_type() == at::kHalf ||
21	                x1_flat.scalar_type() == at::kFloat ||
22	                x1_flat.scalar_type() == at::kBFloat16,
23	                "foreach_lerp_scalar: only float16, float32 and bfloat16 are supported, got ",
24	                x1_flat.scalar_type());
25	    TORCH_CHECK(x1_flat.scalar_type() == x2_flat.scalar_type(),
26	                "foreach_lerp_scalar: x1 and x2 must have the same dtype");
27	    TORCH_CHECK(x1_flat.numel() == x2_flat.numel(),
28	                "foreach_lerp_scalar: x1 and x2 must have the same number of elements");
29	    TORCH_CHECK(x1_flat.is_contiguous() && x2_flat.is_contiguous(),
30	                "foreach_lerp_scalar: inputs must be contiguous");
31	
32	    at::Tensor output = at::empty_like(x1_flat);
33	
34	    int64_t totalLength = x1_flat.numel();
35	    if (totalLength == 0) {
36	        return output;
37	    }
38	
39	    int64_t dtypeSize = static_cast<int64_t>(x1_flat.element_size());
40	
41	    // ---- 获取硬件参数 ----
42	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
43	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
44	    uint64_t ubSize;
45	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
46	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
47	
48	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
49	    int64_t totalLengthCoreAlign = totalLength;
50	    if (totalLength >= coreNum) {
51	        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
52	        int64_t alignNum = CACHE_LINE_BYTE_LENGTH / dtypeSize;
53	        if (alignNum == 0) { alignNum = 1; }
54	        totalLengthCoreAlign = ((totalLengthCore + alignNum - 1) / alignNum) * alignNum;
55	    }
56	
57	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
58	    if (usedCoreNum < 1) { usedCoreNum = 1; }
59	    int64_t formerNum = usedCoreNum - 1;
60	    int64_t formerLength = totalLengthCoreAlign;
61	    int64_t tailLength = totalLength - formerNum * formerLength;
62	
63	    // ---- UB 级 tiling (核内切分) ----
64	    // bufferCoefficient: 32 for FP32, 24 for FP16/BF16
65	    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;
66	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
67	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
68	    if (dtypeSize == 0) { dtypeSize = 1; }
69	    int64_t alignElements = 32 / dtypeSize;
70	    if (alignElements == 0) { alignElements = 1; }
71	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
72	    if (tileLength < alignElements) { tileLength = alignElements; }
73	
74	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
75	
76	    float weight = static_cast<float>(scalar_weight);
77	
78	    EXEC_KERNEL_CMD(foreach_lerp_scalar, blockDim,
79	                    x1_flat, x2_flat, output,
80	                    formerNum, formerLength, tailLength, tileLength,
81	                    dtypeSize, weight);
82	
83	    return output;
84	}
85	
86	}  // namespace ascend_kernel
